import React, { useEffect } from 'react';
import { StyleSheet, Text, View, TouchableOpacity, Image, SafeAreaView, ScrollView, ImageBackground, Platform } from 'react-native';
import { StackNavigationProp } from '@react-navigation/stack';
import { RootStackParamList } from '../App';
import { MaterialIcons, Ionicons } from '@expo/vector-icons';
import Logo from '../components/Logo';
import { COLORS } from '../constants/theme';
import { LinearGradient } from 'expo-linear-gradient';
import { useLocalization } from '../i18n/localizationContext';

type HomeScreenNavigationProp = StackNavigationProp<RootStackParamList, 'Home'>;

type Props = {
  navigation: HomeScreenNavigationProp;
};

const HomeScreen: React.FC<Props> = ({ navigation }) => {
  const { t } = useLocalization();
  // Add debug logging for component lifecycle
  useEffect(() => {
    console.log("HomeScreen: Component mounted");

    return () => {
      console.log("HomeScreen: Component unmounted");
    };
  }, []);

  const navigateToCamera = (analysisType: 'facial' | 'eye' | 'hairScalp' = 'facial') => {
    console.log(`HomeScreen: Navigating to Camera for ${analysisType} analysis`);
    navigation.navigate('Camera', { mode: analysisType });
  };

  const navigateToLogoGenerator = () => {
    console.log("HomeScreen: Navigating to Logo Generator");
    navigation.navigate('LogoGenerator');
  };

  const navigateToPrivacyPolicy = () => {
    console.log("HomeScreen: Navigating to Privacy Policy");
    navigation.navigate('PrivacyPolicy');
  };

  const navigateToSettings = () => {
    console.log("HomeScreen: Navigating to Settings");
    navigation.navigate('Settings');
  };

  const navigateToBeforeAfterAnalysis = () => {
    console.log("HomeScreen: Navigating to Before/After Analysis");
    navigation.navigate('BeforeAfterAnalysis', { beforeImage: '', afterImage: '' });
  };

  console.log("HomeScreen: Rendering");

  try {
    return (
      <SafeAreaView style={styles.container}>
        <LinearGradient
          colors={[COLORS.primary.dark, COLORS.primary.main, 'rgba(255,255,255,0.9)']}
          locations={[0, 0.7, 1]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 0 }}
          style={styles.headerGradient}
        >
          <View style={styles.header}>
            <View style={styles.logoWrapper}>
              <Logo size="large" showTagline={true} color="white" />
            </View>
            <TouchableOpacity
              style={styles.settingsButton}
              onPress={navigateToSettings}
            >
              <Ionicons name="settings-outline" size={28} color="white" />
            </TouchableOpacity>
          </View>
        </LinearGradient>

        <ScrollView style={styles.content}>
          <View style={styles.heroContainer}>
            <ImageBackground
              source={require('../assets/images/beauty_hero.jpg')}
              style={styles.heroImage}
              resizeMode="cover"
            >
              <View style={styles.heroOverlay}>
                <Text style={styles.heroTitle}>
                  AI-Powered Skin Analysis
                </Text>
                <Text style={styles.heroSubtitle}>
                  Get personalized skincare recommendations based on advanced AI analysis
                </Text>
              </View>
            </ImageBackground>
          </View>

          <View style={styles.actionContainer}>
            <TouchableOpacity
              style={[styles.actionButton, styles.primaryButton]}
              onPress={() => navigateToCamera('facial')}
            >
              <MaterialIcons name="camera-alt" size={24} color="white" style={styles.actionButtonIcon} />
              <Text style={styles.actionButtonText}>{t('facialAnalysisButton')}</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.actionButton, styles.primaryButton, styles.marginTopButton]}
              onPress={() => navigateToCamera('eye')}
            >
              <MaterialIcons name="visibility" size={24} color="white" style={styles.actionButtonIcon} />
              <Text style={styles.actionButtonText}>{t('eyeAnalysisButton')}</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.actionButton, styles.primaryButton, styles.marginTopButton]}
              onPress={navigateToBeforeAfterAnalysis}
            >
              <MaterialIcons name="compare" size={24} color="white" style={styles.actionButtonIcon} />
              <Text style={styles.actionButtonText}>{t('beforeAfterButton')}</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.actionButton, styles.primaryButton, styles.marginTopButton]}
              onPress={() => navigateToCamera('hairScalp')}
            >
              <MaterialIcons name="science" size={24} color="white" style={styles.actionButtonIcon} />
